// Untested lyrics avenues on the sampled whitelisted songs, all video-ID keyed except LRCLIB:
//  desc      - video description contains a lyrics-like block (>=6 lines of Hebrew/Yiddish/Latin text)
//  captions  - manual (non-ASR) caption tracks on the video; asr = auto-generated only
//  counterpart - YouTube Music lyrics tab on the song/video counterpart of this id
//  lrclib-clean - LRCLIB search with the bilingual "English - Hebrew" channel name split into each half
import fs from "node:fs";
import { cred } from "./lib.mjs";
import { CLIENTS } from "../clients.mjs";
const WEB = CLIENTS.find((c) => c.key === "WEB");
const rows = JSON.parse(fs.readFileSync(new URL("./.cache/lyrics-coverage.json", import.meta.url), "utf8"));
const LIMIT = Number(process.env.LIMIT || 60);
const { visitorData } = await cred();
const ctx = { client: { clientName: "WEB_REMIX", clientVersion: "1.20250310.01.00", hl: "en", gl: "US", visitorData } };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function post(ep, body) {
  const r = await fetch(`https://music.youtube.com/youtubei/v1/${ep}?prettyPrint=false`, {
    method: "POST", headers: { "Content-Type": "application/json", "X-Goog-Visitor-Id": visitorData, Origin: "https://music.youtube.com", "User-Agent": "Mozilla/5.0" },
    body: JSON.stringify({ context: ctx, ...body }),
  });
  return r.status === 200 ? r.json() : null;
}
async function ytLyrics(videoId) {
  const n = await post("next", { videoId });
  const tabs = n?.contents?.singleColumnMusicWatchNextResultsRenderer?.tabbedRenderer?.watchNextTabbedResultsRenderer?.tabs || [];
  const ep = tabs.map((t) => t.tabRenderer?.endpoint?.browseEndpoint).find((e) => e?.browseId?.startsWith("MPLYt"));
  if (!ep || tabs[1]?.tabRenderer?.unselectable) return { text: null, n };
  const b = await post("browse", { browseId: ep.browseId, params: ep.params });
  return { text: b?.contents?.sectionListRenderer?.contents?.[0]?.musicDescriptionShelfRenderer?.description?.runs?.[0]?.text || null, n };
}
function counterpartIds(n) {
  const out = new Set();
  const walk = (o) => { if (!o || typeof o !== "object") return; if (o.counterpart) for (const c of o.counterpart) { const id = c.counterpartRenderer?.playlistPanelVideoRenderer?.navigationEndpoint?.watchEndpoint?.videoId; if (id) out.add(id); } for (const v of Object.values(o)) walk(v); };
  walk(n); return [...out];
}
const lyricLine = /[֐-׿]{2,}|[A-Za-z']{2,}/;
function descHasLyrics(d) {
  const lines = (d || "").split("\n").map((l) => l.trim());
  let run = 0, best = 0;
  for (const l of lines) { if (l && l.length < 80 && !/https?:|@|#|℗|©|℗|instagram|spotify|apple|itunes|download|subscribe|produced|arranged|mix|master|lyrics by|music by|composed|כתיבה|לחן|עיבוד|הפקה|מיקס|צילום|בימוי|הזמנות|להזמנת/i.test(l) && lyricLine.test(l)) { run++; best = Math.max(best, run); } else run = 0; }
  return best;
}
async function lrclib(title, artist) {
  const u = new URL("https://lrclib.net/api/search"); u.searchParams.set("track_name", title); u.searchParams.set("artist_name", artist);
  const r = await fetch(u, { headers: { "User-Agent": "zemer-coverage-probe/1.0" } }); if (r.status !== 200) return `HTTP${r.status}`;
  const d = await r.json(); const hit = d.find((t) => t.syncedLyrics) || d.find((t) => t.plainLyrics);
  return hit ? `${hit.syncedLyrics ? "LINE" : "PLAIN"} "${hit.trackName} — ${hit.artistName}"` : "NONE";
}
const cleanTitle = (t) => t.replace(/\s*[\(\[][^\)\]]*(official|video|audio|lyric|clip|feat|ft\.|קליפ|רשמי)[^\)\]]*[\)\]]/gi, "").replace(/\s*\|.*$/, "").trim();
const tally = { hasCounterpart: 0, desc: 0, manualCaptions: 0, asrOnly: 0, counterpartLyrics: 0, lrclibClean: 0 };
const notes = [];
for (const s of rows.slice(0, LIMIT)) {
  const line = [];
  try {
    const { text, n } = await ytLyrics(s.id);
    const cps = counterpartIds(n);
    if (cps.length) tally.hasCounterpart++;
    if (!text) for (const cid of cps) { const c = await ytLyrics(cid); if (c.text) { tally.counterpartLyrics++; line.push(`counterpart-lyrics ${cid}`); break; } }
    let gotDesc = false, gotManual = false, gotAsr = false;
    for (const vid of [s.id, ...cps]) {
      const pr = await fetch("https://www.youtube.com/youtubei/v1/player?prettyPrint=false", { method: "POST", headers: { "Content-Type": "application/json", "X-Goog-Visitor-Id": visitorData, "User-Agent": "Mozilla/5.0" },
        body: JSON.stringify({ context: { client: { clientName: WEB.clientName, clientVersion: WEB.clientVersion, hl: "en", gl: "US", visitorData } }, videoId: vid }) });
      const p = pr.status === 200 ? await pr.json() : null;
      const desc = p?.videoDetails?.shortDescription || "";
      if (/Auto-generated by YouTube/.test(desc)) continue;
      const run = descHasLyrics(desc);
      if (run >= 6 && !gotDesc) { gotDesc = true; line.push(`desc(${run} lines, ${vid})`); }
      const tracks = p?.captions?.playerCaptionsTracklistRenderer?.captionTracks || [];
      const manual = tracks.filter((t) => t.kind !== "asr");
      if (manual.length && !gotManual) { gotManual = true; line.push(`captions[${manual.map((t) => t.languageCode).join(",")}] ${vid}`); }
      else if (tracks.length) gotAsr = true;
    }
    if (gotDesc) tally.desc++; if (gotManual) tally.manualCaptions++; else if (gotAsr) tally.asrOnly++;
    const halves = s.artist.split(/\s+-\s+/).map((x) => x.trim()).filter(Boolean);
    let lr = "NONE";
    for (const a of halves) { lr = await lrclib(cleanTitle(s.title), a); if (lr.startsWith("LINE") || lr.startsWith("PLAIN")) break; }
    if (lr.startsWith("LINE") || lr.startsWith("PLAIN")) { tally.lrclibClean++; line.push(`lrclib ${lr}`); }
  } catch (e) { line.push(`ERR ${String(e).slice(0, 60)}`); }
  if (line.length) notes.push(`${s.artist} — ${s.title} (${s.id}): ${line.join(" | ")}`);
  await sleep(400);
}
console.log(`n=${Math.min(LIMIT, rows.length)}`, tally);
notes.forEach((x) => console.log("  " + x));
